}
","strings":{}},{"widgetId":"832a29738c2b44fdb4e63369b1bf458a","version":78,"js":"","css":".widget-832a29 .accordion-wrapper {
  list-style-type: none;
  text-align: left;
  overflow: hidden;
  margin: 0;
}

.widget-832a29 .accordion-title {
  display: flex;
  align-items: center;
}

.widget-832a29 .title-text {
  display: flex;
  align-items: center;
}

.widget-832a29 .title-text > * {
  margin: 0;
}

.widget-832a29 .title-icon {
  width: 30px;
  fill: currentColor;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

#dm .widget-832a29 .accordion-title .title-text {
  font-size: 16px;
  font-weight: 600;
  flex-grow: 1;
}

.widget-832a29 .section {
  overflow: hidden;
  transition: max-height 0.3s ease-out;
  height: auto;
  max-height: 0;
  font-size: 16px;
}

.widget-832a29 .expanded .section, [data-first-expanded='true'] .accordion-item:first-of-type .section {
  max-height: 30000px;
}

.widget-832a29 .section-inner {
  padding: 18px 20px;
  margin: 0;
}

.widget-832a29 .section-inner ul {
  padding-left: 40px;
  list-style-type: disc;
  list-style-position: outside;
}

.widget-832a29 .arrow {
  transition: transform 0.3s ease-in-out;
  display: flex;
  flex-direction: column;
  position: relative;
  flex-shrink: 0;
  cursor: pointer;
}

.widget-832a29 .arrow .close {
  width: 100%;
  height: 100%;
}

/* plus and minus signs animation*/
.widget-832a29 .vertical {
  transition: all 0.5s ease-in-out;
  transform: rotate(-90deg);
  position: absolute;
  background-color: #000;
  background-color: currentColor;
  width: 10%;
  height: 100%;
  left: 50%;
  margin-left: -5%;
  top: 50%;
  margin-top: -50%;
}

.widget-832a29 .horizontal {
  transition: all 0.5s ease-in-out;
  transform: rotate(-90deg);
  background-color: #000;
  background-color: currentColor;
  position: absolute;
  width: 100%;
  height: 10%;
  left: 50%;
  margin-left: -50%;
  top: 50%;
  margin-top: -5%;
  opacity: 1;
}

.widget-832a29 .expanded .vertical, [data-first-expanded='true'] .accordion-item:first-of-type .vertical {
  transform: rotate(90deg);
}

.widget-832a29 .expanded .horizontal, [data-first-expanded='true'] .accordion-item:first-of-type .horizontal {
  transform: rotate(90deg);
  opacity: 0;
}

